c='''def grade(score):
    if score >= 85: return 'A'
    if score >= 70: return 'B'
    if score >= 60: return 'C'
    if score >= 47: return 'D'
    return 'E' '''
add('5:b',['B2.3.2'],'Construct grade(score) in Python for an integer from35 to100. Grades are A for85–100,B for70–84,C for60–69,D for47–59 and E for35–46.','One solution:\n'+c,[(1,'Correct upper thresholds in a suitable order.'),(1,'Each band returns the specified grade without overlap.'),(1,'Correct remaining lowest band.')],status='B',code=c,source_issues=['Source prose overlaps grade69; source table uses70 asB lower threshold. Adapted bounds explicit.'],test_code=c+'\nassert [grade(x) for x in [35,46,47,59,60,69,70,84,85,100]]==["E","E","D","D","C","C","B","B","A","A"]',check='All lower/upper grade boundaries executed.')
add('5:c',['B2.1.2','B2.1.3'],'A Python program evaluates full_name.index(" "). Outline why it raises ValueError when full_name is "Isabella".','The string contains no space, so index cannot find the requested substring and signals failure with ValueError.',[(1,'Requested delimiter/substring absent.'),(1,'index raises ValueError rather than returning a valid position.')],status='B',source_issues=['Source FIND(A2," ") reverses the usual spreadsheet arguments; its displayed results assume FIND(" ",A2). Rewritten Python semantics explicit.'],test_code='try:\n "Isabella".index(" ")\n raise AssertionError("missing ValueError")\nexcept ValueError:pass',check='Executed missing-space case.')
c='''def first_space_or_false(name):
    try:
        return name.index(' ')
    except ValueError:
        return False'''
add('5:d',['B2.1.3'],'Construct first_space_or_false(name) in Python. Return the zero-based index of the first space, or the Boolean False if no space exists. Use try/except to handle the missing-space case.','One solution:\n'+c,[(1,'Attempts index lookup in try.'),(1,'Catches ValueError.'),(1,'Returns index on success and False on failure.')],status='B',code=c,test_code=c+'\nassert first_space_or_false("Ari Moss")==3\nassert first_space_or_false("Isabella") is False',check='Both present and absent delimiters executed.')
add('5:e',['B2.1.2'],'Names contain a first name,zero or more middle names,and a final surname token separated by single spaces. Explain how a program can extract the final surname while ignoring middle names.','Find the final space,then take the substring after it; if there is no space,the whole string is the only token. Under the stated format,the last token is the surname. Compound surnames would require different metadata or a different format.',[(1,'Locates last delimiter rather than first.'),(1,'Extracts suffix after that delimiter.'),(1,'Ignores preceding middle-name tokens.'),(1,'Correct handling of single token or justified format assumption.')],status='B')
