c='''def scale_scores(scores):
    result = []
    for score in scores:
        result.append(round((score-20)/(80-20)*(95-30)+30))
    return result'''
add('6:b',['B2.2.2','B2.3.3'],'Construct scale_scores(scores) in Python. For each score s,calculate (s-20)/(80-20)*(95-30)+30,round to the nearest integer using Python round,and store the result in a new list in the same order.','One solution:\n'+c,[(1,'Loops over every input score.'),(1,'Correct supplied calculation and rounding.'),(1,'Builds/returns corresponding output list in order.')],status='B',code=c,test_code=c+'\nassert scale_scores([20,50,80])==[30,62,95]',check='Endpoints and midpoint executed; Python round tie convention explicitly specified.')
