c='''def high_percentage(scores):
    count = 0
    for score in scores:
        if 91 <= score <= 100:
            count += 1
    return count / len(scores) * 100'''
add('6:d',['B2.2.2','B2.3.2','B2.3.3'],'Construct high_percentage(scores) for a nonempty Python list of numerical scores. Return the percentage of entries between91 and100 inclusive.','One solution:\n'+c,[(1,'Initializes and traverses count.'),(1,'Correct inclusive condition.'),(1,'Counts qualifying entries only.'),(1,'Divides by total and multiplies by100.')],status='B',code=c,test_code=c+'\nassert high_percentage([90,91,100,101])==50\nassert high_percentage([40])==0',check='Both qualifying boundaries and adjacent values executed.')
